<?php

namespace App\Modules\Core\Application\Api;

/** Generates packages/api-client/src/generated.ts from the OpenAPI document (SRS FR-API-03). */
final class TypeScriptClientGenerator
{
    /** @param array<string, mixed> $document */
    public function generate(array $document): string
    {
        $out = [
            '// Generated by `php artisan vsn:openapi`. Do not edit by hand.',
            '/* eslint-disable */',
            '',
        ];

        foreach ($document['components']['schemas'] as $name => $schema) {
            $out[] = 'export type '.$name.' = '.$this->type($schema).';';
            $out[] = '';
        }

        $out[] = 'export interface ClientOptions {';
        $out[] = '  baseUrl?: string;';
        $out[] = '  token?: string;';
        $out[] = '  workspaceId?: string;';
        $out[] = '  brandId?: string;';
        $out[] = '  fetch?: typeof fetch;';
        $out[] = '  credentials?: RequestCredentials;';
        $out[] = '}';
        $out[] = '';
        $out[] = 'export class ApiError extends Error {';
        $out[] = '  constructor(public readonly status: number, public readonly problem: Problem) {';
        $out[] = '    super(problem.title);';
        $out[] = '  }';
        $out[] = '}';
        $out[] = '';
        $out[] = 'export function createClient(options: ClientOptions = {}) {';
        $out[] = "  const base = options.baseUrl ?? '/api/v1';";
        $out[] = '  const doFetch = options.fetch ?? fetch;';
        $out[] = '  async function request<T>(method: string, path: string, query?: Record<string, string | number | undefined>, body?: unknown): Promise<T> {';
        $out[] = "    const headers: Record<string, string> = { Accept: 'application/json' };";
        $out[] = "    if (body !== undefined) headers['Content-Type'] = 'application/json';";
        $out[] = '    if (options.token) headers.Authorization = `Bearer ${options.token}`;';
        $out[] = "    if (options.workspaceId) headers['X-Workspace-Id'] = options.workspaceId;";
        $out[] = "    if (options.brandId) headers['X-Brand-Id'] = options.brandId;";
        $out[] = '    const qs = query ? Object.entries(query).filter(([, v]) => v !== undefined).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`).join(\'&\') : \'\';';
        $out[] = "    const response = await doFetch(`\${base}\${path}\${qs ? `?\${qs}` : ''}`, { method, headers, body: body === undefined ? undefined : JSON.stringify(body), credentials: options.credentials ?? 'include' });";
        $out[] = '    if (response.status === 204) return undefined as T;';
        $out[] = '    const payload = await response.json();';
        $out[] = '    if (!response.ok) throw new ApiError(response.status, payload as Problem);';
        $out[] = '    return payload as T;';
        $out[] = '  }';
        $out[] = '';
        $out[] = '  return {';

        foreach ($document['paths'] as $path => $operations) {
            foreach ($operations as $method => $operation) {
                $out[] = '    '.$this->operation((string) $path, (string) $method, $operation).',';
            }
        }

        $out[] = '  };';
        $out[] = '}';
        $out[] = '';
        $out[] = 'export type ApiClient = ReturnType<typeof createClient>;';
        $out[] = '';

        return implode("\n", $out);
    }

    /** @param array<string, mixed> $operation */
    private function operation(string $path, string $method, array $operation): string
    {
        $args = [];
        $pathExpr = $path;
        $query = [];
        foreach ($operation['parameters'] ?? [] as $parameter) {
            if (isset($parameter['$ref'])) {
                continue;
            }
            if ($parameter['in'] === 'path') {
                $args[] = $parameter['name'].': string';
                $pathExpr = str_replace('{'.$parameter['name'].'}', '${encodeURIComponent('.$parameter['name'].')}', $pathExpr);
            } elseif ($parameter['in'] === 'query') {
                $query[] = '"'.$parameter['name'].'"?: '.($parameter['schema']['type'] === 'integer' ? 'number' : 'string');
            }
        }
        if ($query !== []) {
            $args[] = 'query: { '.implode('; ', $query).' } = {}';
        }
        $body = 'undefined';
        $bodyRef = $operation['requestBody']['content']['application/json']['schema']['$ref'] ?? null;
        if (is_string($bodyRef)) {
            array_unshift($args, 'body: '.$this->refName($bodyRef));
            $body = 'body';
        }

        $result = 'void';
        foreach ($operation['responses'] as $status => $response) {
            if ((int) $status >= 200 && (int) $status < 300 && isset($response['content'])) {
                $result = $this->refName($response['content']['application/json']['schema']['$ref']);
            }
        }

        return sprintf(
            '%s: (%s) => request<%s>(\'%s\', `%s`, %s, %s)',
            $operation['operationId'],
            implode(', ', $args),
            $result,
            strtoupper($method),
            $pathExpr,
            $query !== [] ? 'query' : 'undefined',
            $body,
        );
    }

    /** @param array<string, mixed> $schema */
    private function type(array $schema): string
    {
        if (isset($schema['$ref'])) {
            return $this->refName($schema['$ref']);
        }
        if (isset($schema['const'])) {
            return "'".$schema['const']."'";
        }
        $types = (array) ($schema['type'] ?? 'unknown');
        $parts = [];
        foreach ($types as $type) {
            $parts[] = match ($type) {
                'string' => 'string',
                'integer', 'number' => 'number',
                'boolean' => 'boolean',
                'null' => 'null',
                'array' => $this->type($schema['items'] ?? []).'[]',
                'object' => $this->object($schema),
                default => 'unknown',
            };
        }

        return implode(' | ', $parts);
    }

    /** @param array<string, mixed> $schema */
    private function object(array $schema): string
    {
        if (! isset($schema['properties'])) {
            return isset($schema['additionalProperties']) ? 'Record<string, '.$this->type($schema['additionalProperties']).'>' : 'Record<string, unknown>';
        }
        $required = $schema['required'] ?? [];
        $fields = [];
        foreach ($schema['properties'] as $name => $property) {
            $fields[] = $name.(in_array($name, $required, true) ? '' : '?').': '.$this->type($property);
        }

        return '{ '.implode('; ', $fields).' }';
    }

    private function refName(string $ref): string
    {
        return substr($ref, strrpos($ref, '/') + 1);
    }
}
